using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip using the typed metadata
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-tripped: {deserialized}");

// 2) Probe without throwing — TryGetTypeInfo returns false when metadata
//    isn't available instead of throwing InvalidOperationException.
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = null // no resolver → no metadata available
};

bool found = emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo on empty options: found={found}, info={info?.Type?.Name ?? "(null)"}");

// Contrast: the resolver-backed options succeed
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo on configured options: found={found2}, info={info2?.Type?.Name ?? "(null)"}");

record Person(string Name, int Age);

